Buffer Overruns
What does the following program do?
#include <stdio.h>
#define SIZE 10
main() {
int matrix[SIZE*SIZE];
int total_size = SIZE*SIZE;
int* row_ind[SIZE];
for (int i = 0; i <= total_size; i++)
matrix[i] = i;
for (int i = 0; i <= SIZE; i++)
row_ind[i] = &matrix[i*SIZE];
for (int i = 0; i <= SIZE; i++)
printf("a[%d] = %d\n", i, *row_ind[i]);
}
